[
  {
    "title": "哪些請求會觸發預檢",
    "body": "常見觸發條件包括 PUT、DELETE、PATCH，或使用 application/json、自訂標頭等非簡單請求特徵。",
    "examples": [
      "fetch('https://api.example.com/items/7', {\n  method: 'PUT',\n  headers: { 'Content-Type': 'application/json' },\n  body: '{\"name\":\"A\"}'\n})"
    ]
  },
  {
    "title": "預檢交換的標頭",
    "body": "瀏覽器以 OPTIONS 詢問方法與標頭；伺服器用 Access-Control-Allow-* 標頭表示允許的跨來源範圍。",
    "examples": [
      "OPTIONS /items HTTP/1.1\nOrigin: https://app.example\nAccess-Control-Request-Method: PUT\nAccess-Control-Request-Headers: Content-Type"
    ]
  },
  {
    "title": "預檢快取時間",
    "body": "伺服器可用 Access-Control-Max-Age 指定預檢結果的有效秒數，期間內瀏覽器可省略重問。",
    "examples": [
      "Access-Control-Max-Age: 600"
    ]
  }
]
